class Solution:
    def longestValidParentheses(self, s: str) -> int:
        stack, best = [-1], 0               # 栈底：最后一个没匹配上的位置
        for i, c in enumerate(s):
            if c == "(":
                stack.append(i)
            else:
                stack.pop()
                if not stack:               # 这个 ) 没人匹配，成为新的分界线
                    stack.append(i)
                else:
                    best = max(best, i - stack[-1])
        return best

class Solution:
    def longestValidParentheses(self, s: str) -> int:
        def scan(s, opener):
            best = l = r = 0
            for c in s:
                if c == opener:
                    l += 1
                else:
                    r += 1
                if l == r:
                    best = max(best, 2 * r)
                elif r > l:
                    l = r = 0
            return best
        return max(scan(s, "("), scan(s[::-1], ")"))

